import { z } from 'zod'

// ─── Persona picker schema ────────────────────────────────────────────────────

export const personaPickerSchema = z.object({
  persona: z.enum(['solo_artist', 'studio_owner'], {
    required_error: 'Please select how you use InkOS.',
    invalid_type_error: 'Please select how you use InkOS.',
  }),
  fullName: z
    .string()
    .min(2, 'Your name must be at least 2 characters.')
    .max(80, 'Your name must be 80 characters or fewer.'),
  timezone: z.string().min(1, 'Timezone is required.'),
})

// ─── Inferred input types ─────────────────────────────────────────────────────

export type PersonaPickerInput = z.infer<typeof personaPickerSchema>
export type Persona = PersonaPickerInput['persona']

// ─── Discriminated union result type ─────────────────────────────────────────

export type ActionResult<T> =
  | { ok: true; data: T }
  | { ok: false; error: string }

'use server'

import { createClient } from '@/lib/supabase/server'
import { logAuditAction } from '@/lib/audit'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { slugify } from '@/lib/utils'
import {
  personaPickerSchema,
  type ActionResult,
  type Persona,
} from '@/lib/onboarding/schemas'
import { headers } from 'next/headers'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface OnboardingStatus {
  studioId: string | null
  isOnboarded: boolean
  persona: Persona | null
  fullName: string | null
}

// ─── Internal helpers ─────────────────────────────────────────────────────────

/**
 * Returns the requesting IP for rate-limit keying.
 * Falls back to 'unknown' when the header is absent (local dev).
 */
async function getClientIp(): Promise<string> {
  const hdrs = await headers()
  return hdrs.get('x-forwarded-for') ?? hdrs.get('x-real-ip') ?? 'unknown'
}

/**
 * Derives a studio display name from the user's full name.
 * e.g. "Alex Rivera" → "Alex Rivera Tattoo"
 * Only used when the studio name is the signup default "My Studio".
 */
function autoStudioName(fullName: string): string {
  const trimmed = fullName.trim()
  if (!trimmed) return 'My Studio'
  return `${trimmed} Tattoo`
}

/**
 * Returns a unique slug by appending 4 random hex chars if the given slug
 * is already taken by another studio.
 */
async function resolveUniqueStudioSlug(
  supabase: Awaited<ReturnType<typeof createClient>>,
  currentStudioId: string,
  slug: string,
): Promise<string> {
  const { data: conflict } = await supabase
    .from('studios')
    .select('id')
    .eq('slug', slug)
    .neq('id', currentStudioId)
    .maybeSingle()

  if (!conflict) return slug

  const suffix = Math.floor(Math.random() * 0xffff)
    .toString(16)
    .padStart(4, '0')
  return `${slug}-${suffix}`
}

// ─── completeOnboardingWithPersona ────────────────────────────────────────────

export async function completeOnboardingWithPersona(
  studioId: string,
  input: unknown,
): Promise<ActionResult<{ redirectTo: string }>> {
  const ip = await getClientIp()
  const { success: allowed } = await authedRatelimit.limit(ip)
  if (!allowed) {
    return { ok: false, error: 'Too many requests. Please wait a moment and try again.' }
  }

  const supabase = await createClient()
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()

  if (authError || !user) {
    return { ok: false, error: 'Not authenticated.' }
  }

  // Validate member is the owner
  const { data: member, error: memberError } = await supabase
    .from('studio_members')
    .select('role')
    .eq('studio_id', studioId)
    .eq('user_id', user.id)
    .single()

  if (memberError || !member) {
    return { ok: false, error: 'Studio not found.' }
  }

  if (member.role !== 'owner') {
    return { ok: false, error: 'Only the studio owner can complete onboarding.' }
  }

  const parsed = personaPickerSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.errors[0]?.message ?? 'Invalid input.' }
  }
  const data = parsed.data

  // Fetch current studio
  const { data: currentStudio, error: studioFetchError } = await supabase
    .from('studios')
    .select('id, name, slug')
    .eq('id', studioId)
    .single()

  if (studioFetchError || !currentStudio) {
    logger.error({ studioId, err: studioFetchError }, 'completeOnboardingWithPersona: studio fetch failed')
    return { ok: false, error: "We couldn't save your profile. Try again, or refresh the page." }
  }

  // Auto-derive studio name if still default
  const isDefaultName = currentStudio.name === 'My Studio' || !currentStudio.name
  const newStudioName = isDefaultName ? autoStudioName(data.fullName) : currentStudio.name

  // Compute slug from new name if we're changing it
  let finalSlug = currentStudio.slug
  if (isDefaultName) {
    const rawSlug = slugify(newStudioName)
    if (rawSlug && rawSlug !== currentStudio.slug) {
      finalSlug = await resolveUniqueStudioSlug(supabase, studioId, rawSlug)
    }
  }

  // Update studio name + slug + timezone + mark onboarded
  const { error: studioUpdateError } = await supabase
    .from('studios')
    .update({
      name: newStudioName,
      slug: finalSlug,
      timezone: data.timezone,
      onboarded_at: new Date().toISOString(),
    })
    .eq('id', studioId)

  if (studioUpdateError) {
    logger.error({ studioId, err: studioUpdateError }, 'completeOnboardingWithPersona: studio update failed')
    return { ok: false, error: "We couldn't save your profile. Try again, or refresh the page." }
  }

  // Update profile: full_name + onboarding_persona + onboarded_at
  const { error: profileUpdateError } = await supabase
    .from('profiles')
    .update({
      full_name: data.fullName,
      onboarding_persona: data.persona,
      onboarded_at: new Date().toISOString(),
    })
    .eq('id', user.id)

  if (profileUpdateError) {
    logger.error({ userId: user.id, err: profileUpdateError }, 'completeOnboardingWithPersona: profile update failed')
    // Non-fatal — continue
  }

  // Upsert artist row (solo_artist persona: user IS the artist)
  const { data: existingArtist } = await supabase
    .from('artists')
    .select('id')
    .eq('studio_id', studioId)
    .eq('profile_id', user.id)
    .maybeSingle()

  if (existingArtist) {
    const { error: artistUpdateError } = await supabase
      .from('artists')
      .update({ display_name: data.fullName, specialties: [] })
      .eq('id', existingArtist.id)

    if (artistUpdateError) {
      logger.error({ studioId, userId: user.id, err: artistUpdateError }, 'completeOnboardingWithPersona: artist update failed')
    }
  } else {
    const { error: artistInsertError } = await supabase
      .from('artists')
      .insert({
        studio_id: studioId,
        profile_id: user.id,
        display_name: data.fullName,
        specialties: [],
      })

    if (artistInsertError) {
      logger.error({ studioId, userId: user.id, err: artistInsertError }, 'completeOnboardingWithPersona: artist insert failed')
    }
  }

  await logAuditAction(
    user.id,
    'onboarding.persona_completed',
    { type: 'profile', id: user.id },
    { persona: data.persona },
    studioId,
  )

  return { ok: true, data: { redirectTo: '/dashboard' } }
}

// ─── getOnboardingStatus ──────────────────────────────────────────────────────

export async function getOnboardingStatus(): Promise<OnboardingStatus> {
  const supabase = await createClient()

  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()

  if (authError || !user) {
    return { studioId: null, isOnboarded: false, persona: null, fullName: null }
  }

  // Fetch studio membership
  const { data: memberRow } = await supabase
    .from('studio_members')
    .select('studio_id, studios(onboarded_at)')
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('joined_at', { ascending: true })
    .limit(1)
    .single()

  if (!memberRow) {
    return { studioId: null, isOnboarded: false, persona: null, fullName: null }
  }

  const studioData = Array.isArray(memberRow.studios)
    ? memberRow.studios[0]
    : memberRow.studios

  const isOnboarded = !!(studioData?.onboarded_at)

  const { data: profile } = await supabase
    .from('profiles')
    .select('full_name, onboarding_persona')
    .eq('id', user.id)
    .single()

  const persona = (profile?.onboarding_persona ?? null) as Persona | null
  const fullName = profile?.full_name ?? null

  return {
    studioId: memberRow.studio_id,
    isOnboarded,
    persona,
    fullName,
  }
}

import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import type { Persona } from '@/lib/onboarding/schemas'

/**
 * Server-side persona gate. Call at the top of any page that requires a
 * specific persona. Redirects to /dashboard with a `?reason=persona_required`
 * query param if the user's persona is not in the allowed list.
 *
 * Users with persona = null (pre-migration accounts) are allowed through to
 * preserve backward compatibility — they see all pages until they re-onboard.
 *
 * Usage:
 *   await requirePersona(['studio_owner'])
 */
export async function requirePersona(allowed: readonly Persona[]): Promise<void> {
  const supabase = await createClient()

  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()

  if (authError || !user) {
    redirect('/login')
  }

  const { data: profile } = await supabase
    .from('profiles')
    .select('onboarding_persona')
    .eq('id', user.id)
    .single()

  const persona = profile?.onboarding_persona as Persona | null | undefined

  // Null persona = pre-migration user: allow through (backward compat)
  if (persona === null || persona === undefined) return

  if (!allowed.includes(persona)) {
    redirect('/dashboard?reason=persona_required')
  }
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { completeOnboardingWithPersona } from '@/app/actions/onboarding'
import type { Persona } from '@/lib/onboarding/schemas'

// ─── Timezone detection ───────────────────────────────────────────────────────

function detectBrowserTimezone(): string {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || 'America/New_York'
  } catch {
    return 'America/New_York'
  }
}

// ─── Persona card data ────────────────────────────────────────────────────────

interface PersonaOption {
  value: Persona
  label: string
  description: string
  ariaLabel: string
}

const PERSONAS: PersonaOption[] = [
  {
    value: 'solo_artist',
    label: 'Solo artist',
    description: 'You work independently — freelance, chair rental, or your own micro-studio.',
    ariaLabel: 'Solo artist — you work independently',
  },
  {
    value: 'studio_owner',
    label: 'Studio owner',
    description: 'You run a shop with multiple artists, a front desk, and a team to manage.',
    ariaLabel: 'Studio owner — you run a shop with a team',
  },
]

// ─── Props ────────────────────────────────────────────────────────────────────

interface PersonaPickerProps {
  studioId: string
  initialFullName?: string | null
}

// ─── Component ────────────────────────────────────────────────────────────────

export function PersonaPicker({ studioId, initialFullName }: PersonaPickerProps) {
  const router = useRouter()

  const [selected, setSelected] = useState<Persona | null>(null)
  const [fullName, setFullName] = useState(initialFullName ?? '')
  const [timezone, setTimezone] = useState('')
  const [isPending, setIsPending] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [focusedIndex, setFocusedIndex] = useState(0)

  const cardRefs = useRef<(HTMLButtonElement | null)[]>([])
  const titleRef = useRef<HTMLHeadingElement>(null)

  // Auto-detect timezone on mount
  useEffect(() => {
    setTimezone(detectBrowserTimezone())
  }, [])

  // Focus title on mount for accessibility
  useEffect(() => {
    titleRef.current?.focus()
  }, [])

  function handleKeyDown(e: React.KeyboardEvent<HTMLDivElement>) {
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
      e.preventDefault()
      const next = (focusedIndex + 1) % PERSONAS.length
      setFocusedIndex(next)
      cardRefs.current[next]?.focus()
    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
      e.preventDefault()
      const prev = (focusedIndex - 1 + PERSONAS.length) % PERSONAS.length
      setFocusedIndex(prev)
      cardRefs.current[prev]?.focus()
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      setSelected(PERSONAS[focusedIndex]?.value ?? null)
    }
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    if (!selected) {
      setError('Please select how you use InkOS.')
      return
    }
    if (!fullName.trim() || fullName.trim().length < 2) {
      setError('Your name must be at least 2 characters.')
      return
    }

    setIsPending(true)
    setError(null)

    const result = await completeOnboardingWithPersona(studioId, {
      persona: selected,
      fullName: fullName.trim(),
      timezone,
    })

    if (!result.ok) {
      setError(result.error)
      setIsPending(false)
      return
    }

    router.replace('/dashboard')
  }

  return (
    <div className="min-h-screen bg-bone flex items-center justify-center px-4 py-8">
      <div className="w-full max-w-lg">
        {/* Wordmark */}
        <div className="flex items-center gap-2.5 mb-8 justify-center">
          <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-onyx text-bone">
            <span className="font-serif italic text-xl leading-none">i</span>
          </div>
          <div className="flex flex-col">
            <span className="font-sans text-lg font-bold leading-none text-onyx">InkOS</span>
            <span className="font-sans text-[10px] font-semibold uppercase tracking-[0.08em] text-stone leading-none mt-0.5">
              Studio OS
            </span>
          </div>
        </div>

        {/* Card */}
        <div className="w-full bg-bone rounded-2xl shadow-soft-md border border-border p-6 sm:p-10">
          <form onSubmit={handleSubmit} noValidate>
            {/* Title */}
            <h1
              ref={titleRef}
              tabIndex={-1}
              className="font-serif text-[32px] text-onyx leading-tight focus:outline-none"
            >
              How do you use InkOS?
            </h1>
            <p className="font-sans text-[14px] text-stone mt-1">
              This shapes your workspace. You can change it later.
            </p>

            {/* Persona cards */}
            <div
              role="radiogroup"
              aria-label="Select your persona"
              className="grid grid-cols-1 sm:grid-cols-2 gap-3 mt-6"
              onKeyDown={handleKeyDown}
            >
              {PERSONAS.map((option, idx) => {
                const isSelected = selected === option.value
                return (
                  <button
                    key={option.value}
                    ref={(el) => { cardRefs.current[idx] = el }}
                    type="button"
                    role="radio"
                    aria-checked={isSelected}
                    aria-label={option.ariaLabel}
                    tabIndex={focusedIndex === idx ? 0 : -1}
                    onClick={() => {
                      setSelected(option.value)
                      setFocusedIndex(idx)
                    }}
                    className={[
                      'text-left rounded-xl border p-4 flex flex-col gap-1.5',
                      'transition-all duration-150 ease-out',
                      'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                      isSelected
                        ? 'border-onyx shadow-card-hover'
                        : 'border-border bg-bone hover:border-stone hover:shadow-card',
                    ].join(' ')}
                  >
                    <span className="font-sans text-[15px] font-bold text-onyx leading-snug">
                      {option.label}
                    </span>
                    <span className="font-sans text-[13px] font-normal text-stone leading-snug">
                      {option.description}
                    </span>
                  </button>
                )
              })}
            </div>

            {/* Full name */}
            <div className="mt-6 flex flex-col gap-1.5">
              <Label
                htmlFor="full-name"
                className="font-sans text-[11px] font-bold uppercase tracking-[0.08em] text-stone"
              >
                Your name
              </Label>
              <Input
                id="full-name"
                type="text"
                autoComplete="name"
                placeholder="Alex Rivera"
                value={fullName}
                onChange={(e) => setFullName(e.target.value)}
                className="h-9 bg-bone border-input font-sans text-[14px] text-onyx placeholder:text-stone focus-visible:ring-ring"
                required
                minLength={2}
                maxLength={80}
              />
            </div>

            {/* Error */}
            {error && (
              <p
                role="alert"
                className="font-sans text-[13px] text-destructive mt-3"
              >
                {error}
              </p>
            )}

            {/* Button row */}
            <div className="mt-8 flex items-center justify-end">
              <Button
                type="submit"
                variant="default"
                size="default"
                disabled={isPending}
                aria-busy={isPending}
                className="min-w-[120px]"
              >
                {isPending ? 'Saving…' : 'Open the studio'}
              </Button>
            </div>
          </form>
        </div>
      </div>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { getOnboardingStatus } from '@/app/actions/onboarding'
import { PersonaPicker } from '@/components/onboarding/PersonaPicker'

export const metadata: Metadata = {
  title: 'Welcome to InkOS',
}

export default async function OnboardingPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  const status = await getOnboardingStatus()

  // Already fully onboarded → skip to dashboard
  if (status.isOnboarded) {
    redirect('/dashboard')
  }

  // No studio yet (edge case — signup trigger should have created one)
  if (!status.studioId) {
    redirect('/dashboard')
  }

  return (
    <PersonaPicker
      studioId={status.studioId}
      initialFullName={status.fullName}
    />
  )
}

