import { describe, expect, it } from 'vitest'
import { personaPickerSchema } from '@/lib/onboarding/schemas'

// ─── personaPickerSchema ──────────────────────────────────────────────────────

describe('personaPickerSchema', () => {
  const base = {
    persona: 'solo_artist' as const,
    fullName: 'Alex Rivera',
    timezone: 'America/Los_Angeles',
  }

  it('accepts a valid solo_artist with fullName and timezone', () => {
    expect(personaPickerSchema.safeParse(base).success).toBe(true)
  })

  it('accepts a valid studio_owner', () => {
    const result = personaPickerSchema.safeParse({ ...base, persona: 'studio_owner' })
    expect(result.success).toBe(true)
    if (result.success) {
      expect(result.data.persona).toBe('studio_owner')
    }
  })

  it('rejects an unknown persona value', () => {
    const result = personaPickerSchema.safeParse({ ...base, persona: 'manager' })
    expect(result.success).toBe(false)
  })

  it('rejects missing persona', () => {
    const result = personaPickerSchema.safeParse({ fullName: 'Alex Rivera', timezone: 'America/Los_Angeles' })
    expect(result.success).toBe(false)
  })

  // fullName boundaries
  it('rejects fullName with length 1', () => {
    const result = personaPickerSchema.safeParse({ ...base, fullName: 'X' })
    expect(result.success).toBe(false)
    if (!result.success) {
      expect(result.error.errors[0]?.message).toMatch(/at least 2 characters/)
    }
  })

  it('accepts fullName with length 2', () => {
    expect(personaPickerSchema.safeParse({ ...base, fullName: 'AB' }).success).toBe(true)
  })

  it('accepts fullName with length 80', () => {
    expect(personaPickerSchema.safeParse({ ...base, fullName: 'A'.repeat(80) }).success).toBe(true)
  })

  it('rejects fullName with length 81', () => {
    expect(personaPickerSchema.safeParse({ ...base, fullName: 'A'.repeat(81) }).success).toBe(false)
  })

  // timezone required
  it('rejects empty timezone', () => {
    const result = personaPickerSchema.safeParse({ ...base, timezone: '' })
    expect(result.success).toBe(false)
  })

  it('accepts a valid IANA timezone string', () => {
    expect(personaPickerSchema.safeParse({ ...base, timezone: 'Europe/London' }).success).toBe(true)
  })
})
